#!/usr/bin/env python3
"""Run fkPT2 with a linear spectrum and cosmology generated by CLASS."""

import argparse
import os
from pathlib import Path
import re
import shutil
import subprocess
import sys
import tempfile


PROJECT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(PROJECT / "python"))
local_classy = PROJECT / "build" / "classy"
if (local_classy / "classy").is_dir():
    sys.path.insert(1, str(local_classy))

from fkpt2_class import (
    class_power_parameters,
    class_workflow_solver_options,
    read_class_workflow_ini,
    solver_parameters,
)


def background_at_zero(path):
    columns = []
    last = []
    with path.open(encoding="utf-8") as table:
        for line in table:
            line = line.strip()
            if line.startswith("#"):
                if line[1:].lstrip().startswith("1:z"):
                    columns = re.findall(r"\d+:\s*(.*?)(?=\s+\d+:|$)", line)
            elif line:
                last = line.split()
    if not columns or len(last) != len(columns):
        raise ValueError(f"Could not read the CLASS background columns in {path}")
    return dict(zip(columns, map(float, last)))


def run_binaries(class_path, options, class_bin, fkpt2_bin):
    cosmology, solver_text = read_class_workflow_ini(class_path)
    if solver_text is not None:
        options = class_workflow_solver_options(class_path, solver_text, options)

    class_bin = shutil.which(class_bin)
    if class_bin is None:
        raise ValueError("Build the standalone CLASS executable or set CLASS_BIN to its path")
    fkpt2_bin = shutil.which(fkpt2_bin)
    if fkpt2_bin is None:
        raise ValueError("Build the fkPT2 executable or set FKPT2_BIN to its path")
    class_bin = Path(class_bin).resolve()
    fkpt2_bin = Path(fkpt2_bin).resolve()

    settings = class_power_parameters(cosmology)
    z = settings["z_pk"]
    with tempfile.TemporaryDirectory(prefix="fkpt2-class-") as directory:
        scratch = Path(directory)
        # Keep CLASS output isolated. CLASS appends an underscore to this root.
        prefix = scratch / "linear"
        settings.pop("write background", None)
        settings.update(root=prefix, overwrite_root="yes", write_background="yes", headers="yes")
        input_file = scratch / "class.ini"
        input_file.write_text("".join(f"{name} = {value}\n" for name, value in settings.items()),
                              encoding="utf-8")
        subprocess.run([class_bin, input_file], cwd=class_path.parent, check=True)

        background = background_at_zero(scratch / "linear_background.dat")
        options, use_cb, omega_nu = solver_parameters(background, z, options)
        name = "linear_pk_cb.dat" if use_cb and omega_nu > 0.0 else "linear_pk.dat"
        source = scratch / name
        if not source.is_file():
            raise ValueError(f"CLASS did not produce the expected linear spectrum {name}")

        root = options.get("rootDir", "Output")
        suffix = options.get("suffixModel", "")
        if not root or "/" in suffix:
            raise ValueError("Supply a nonempty rootDir and a suffixModel without slashes")
        output_dir = Path(root)
        output_dir.mkdir(parents=True, exist_ok=True)
        output = output_dir / f"class_linear{suffix}.dat"
        # Publish a complete table and keep fnamePS usable in the run record.
        with tempfile.NamedTemporaryFile(dir=output_dir, prefix=".class-linear-", delete=False) as saved:
            staging = Path(saved.name)
        try:
            shutil.copyfile(source, staging)
            os.replace(staging, output)
        finally:
            staging.unlink(missing_ok=True)
        options["fnamePS"] = output.resolve()
        command = [fkpt2_bin]
        if solver_text is not None:
            # Preserve the original basename in fkPT2's used-values record.
            solver_file = scratch / "fkpt2" / class_path.name
            solver_file.parent.mkdir()
            solver_file.write_text(solver_text, encoding="utf-8")
            command.append(solver_file)
        command.extend(f"{key}={value}" for key, value in options.items())
        subprocess.run(command, check=True)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("class_ini", type=Path,
                        help="CLASS input or a combined [class] and [fkpt2] parameter file")
    parser.add_argument("settings", nargs="*", metavar="key=value", help="fkPT2 solver settings")
    parser.add_argument("--class-bin", help=argparse.SUPPRESS)
    parser.add_argument("--fkpt2-bin", default=str(PROJECT / "fkpt2"), help=argparse.SUPPRESS)
    args = parser.parse_args()
    options = {}
    for setting in args.settings:
        name, sep, value = setting.partition("=")
        if not sep or not name:
            parser.error(f"Expected an fkPT2 key=value setting, got {setting!r}")
        options[name] = value

    class_path = args.class_ini.resolve()
    try:
        if args.class_bin:
            run_binaries(class_path, options, args.class_bin, args.fkpt2_bin)
        else:
            cosmology, solver_text = read_class_workflow_ini(class_path)
            import fkpt2

            # Relative CLASS resource paths are relative to the input file.
            os.chdir(class_path.parent)
            if solver_text is None:
                result = fkpt2.compute_from_class(cosmology, parameters=options)
            else:
                result = fkpt2._compute_classy_paramfile(class_path, options)
            print("# k P0 P2 P4")
            for row in result.multipoles:
                print(" ".join(f"{value:.15e}" for value in row))
    except subprocess.CalledProcessError as exc:
        print(f"{Path(exc.cmd[0]).name} exited with status {exc.returncode}", file=sys.stderr)
        return exc.returncode if exc.returncode > 0 else 1
    except (ImportError, KeyError, OSError, ValueError, RuntimeError) as exc:
        print(f"fkPT2 CLASS workflow: {exc}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
